<?php
header('Content-Type: application/json');require dirname(__DIR__).'/bootstrap.php';try{$auth=isset($_SERVER['HTTP_AUTHORIZATION'])?$_SERVER['HTTP_AUTHORIZATION']:'';if(!preg_match('/^Bearer\s+([a-f0-9]{64})$/i',$auth,$m))throw new RuntimeException('Device is not paired.');$q=$pdo->prepare('SELECT id,user_id FROM gh_api_tokens WHERE token_hash=? AND revoked_at IS NULL');$q->execute(array(hash('sha256',$m[1])));$token=$q->fetch();if(!$token)throw new RuntimeException('Device token is invalid.');if(empty($_FILES['walk']['tmp_name']))throw new RuntimeException('CSV file missing.');$_SERVER['GH_UPLOAD_USER_ID']=(int)$token['user_id'];$_SERVER['GH_UPLOAD_FILE']=$_FILES['walk']['tmp_name'];$_SERVER['GH_UPLOAD_NAME']=$_FILES['walk']['name'];require __DIR__.'/import_walk.php';$pdo->prepare('UPDATE gh_api_tokens SET last_used_at=NOW() WHERE id=?')->execute(array($token['id']));echo json_encode(array('ok'=>true,'duplicate'=>!empty($GLOBALS['GH_DUPLICATE']),'track_id'=>isset($GLOBALS['GH_TRACK_ID'])?$GLOBALS['GH_TRACK_ID']:null));}catch(Exception $e){http_response_code(400);echo json_encode(array('ok'=>false,'error'=>$e->getMessage()));}
